package com.tracksphere.domain.model; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="notifications") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class Notification { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(nullable=false,length=160) private String title; @Column(nullable=false,length=500) private String message; @Column(nullable=false,length=30) private String severity; @Column(name="read_at") private Instant readAt; @Column(name="created_at",nullable=false) private Instant createdAt; public Notification(User user,String title,String message,String severity){id=UUID.randomUUID();this.user=user;this.title=title;this.message=message;this.severity=severity;createdAt=Instant.now();} public void markRead(){readAt=Instant.now();} }
